parameters.jsCode:
for (const item of $input.all()) {
  item.json.start_time = Date.now();
}

return $input.all();

const item = $input.first();
const rawText = item.json.output[0].content[0].text;

let parsed;
try {
  parsed = JSON.parse(rawText);
} catch(e) {
  parsed = { agent_type: 'none', confidence: 0 };
}

const agentType = parsed.agent_type || 'none';
const confidence = parsed.confidence || 0;

// If confidence is low — route to escalation
const routeTo = confidence < 0.7 ? 'ambiguous' : agentType;

return [{
  json: {
    ...item.json,
    agent_type: agentType,
    confidence: confidence,
    route_to: routeTo
  }
}];

